INSERT INTO identities (
    uuid, external_id, organization_uuid, workspace_uuid, namespace, external_subject_id,
    display_name, enabled, auto_memory_store
) VALUES (
    #{params.UUID}, #{params.ExternalID}, #{params.OrganizationUUID}, #{params.WorkspaceUUID},
    #{params.Namespace}, #{params.ExternalSubjectID}, #{params.DisplayName}, #{params.Enabled},
    #{params.AutoMemoryStore}
)
RETURNING

mapper.select:
SELECT 
FROM identities
WHERE workspace_uuid = #{params.WorkspaceUUID} AND deleted_at IS NULL
AND external_id < #{params.Cursor}
AND enabled = true
AND enabled = false
AND external_subject_id = #{params.Subject}
AND namespace = #{params.Namespace}
AND (strpos(lower(display_name), lower(#{params.Search})) > 0 OR strpos(lower(external_subject_id), lower(#{params.Search})) > 0 OR strpos(lower(external_id), lower(#{params.Search})) > 0)
ORDER BY external_id DESC
LIMIT #{params.Limit}

SELECT 
FROM identity_configs
WHERE workspace_uuid = #{workspaceUUID} AND identity_uuid = #{identityUUID} AND status = 'active'
AND agent_external_id = #{agentExternalID}
AND external_id < #{cursor}
ORDER BY external_id DESC
LIMIT #{limit}

mapper.update:
UPDATE identity_configs SET revision = revision + 1, env = CAST(#{params.Env} AS jsonb),
    vault_mounts = CAST(#{params.VaultMounts} AS jsonb), disabled_vaults = CAST(#{params.DisabledVaults} AS jsonb),
    updated_at = now()
WHERE workspace_uuid = #{params.WorkspaceUUID} AND external_id = #{params.ExternalID}
AND status = 'active' AND revision = #{params.ExpectedRevision}

mapper.select:
SELECT 
FROM identity_configs
WHERE workspace_uuid = #{workspaceUUID} AND identity_uuid = #{identityUUID}
AND status IN ('active', 'archived')
AND external_id < #{cursor}
ORDER BY external_id DESC
LIMIT #{limit}

mapper.update:
UPDATE channels SET connection_status = #{status}
WHERE workspace_uuid = #{workspaceUUID} AND external_id = #{channelExternalID}
AND deleted_at IS NULL AND identity_resolution_mode IS NOT NULL
AND connection_status IS DISTINCT FROM #{status}

UPDATE channels SET entry_closed = true, updated_at = now()
WHERE workspace_uuid = #{workspaceUUID} AND identity_uuid = #{identityUUID}
AND identity_resolution_mode = 'fixed' AND entry_closed = false AND deleted_at IS NULL

