INSERT INTO channel_pairings (
    uuid, external_id, organization_uuid, workspace_uuid, channel_uuid, channel_external_id,
    scope_kind, platform_account, remote_id, display_name, pairing_code_hash, pairing_code_expires_at
) VALUES (
    #{params.UUID}, #{params.ExternalID}, #{params.OrganizationUUID}, #{params.WorkspaceUUID},
    #{params.ChannelUUID}, #{params.ChannelExternalID}, #{params.ScopeKind}, #{params.PlatformAccount},
    #{params.RemoteID}, #{params.DisplayName}, #{params.CodeHash,sensitive=true}, #{params.CodeExpiresAt}
)
RETURNING

mapper.select:
SELECT 
FROM channel_pairings
WHERE workspace_uuid = #{workspaceUUID} AND external_id = #{externalID}

SELECT 
FROM channel_pairings
WHERE channel_uuid = #{channelUUID} AND scope_kind = #{scopeKind}
AND platform_account = #{platformAccount} AND remote_id = #{remoteID}
AND status IN ('pending', 'active')

SELECT 
FROM channel_pairings
WHERE workspace_uuid = #{params.WorkspaceUUID} AND status = 'pending'
AND pairing_code_hash = #{params.CodeHash,sensitive=true}
AND pairing_code_expires_at > #{params.Now}

SELECT 
FROM channel_pairings
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND channel_external_id = #{params.ChannelExternalID}
AND status = #{params.Status}
AND external_id < #{params.Cursor}
ORDER BY external_id DESC
LIMIT #{params.Limit}

mapper.update:
UPDATE channel_pairings SET status = 'active', identity_uuid = #{params.IdentityUUID},
    agent_external_id = #{params.AgentExternalID}, agent_version = #{params.AgentVersion},
    revision = 1, pairing_code_hash = NULL, pairing_code_expires_at = NULL, updated_at = #{params.Now}
WHERE workspace_uuid = #{params.WorkspaceUUID} AND external_id = #{params.ExternalID}
AND status = 'pending' AND pairing_code_hash = #{params.CodeHash,sensitive=true}
AND pairing_code_expires_at > #{params.Now}

UPDATE channel_pairings SET identity_uuid = #{params.IdentityUUID},
    agent_external_id = #{params.AgentExternalID}, agent_version = #{params.AgentVersion},
    revision = revision + 1, updated_at = now()
WHERE workspace_uuid = #{params.WorkspaceUUID} AND external_id = #{params.ExternalID}
AND status = 'active' AND revision = #{params.ExpectedRevision}

UPDATE channel_pairings SET status = 'unbound', revision = revision + 1,
    pairing_code_hash = NULL, pairing_code_expires_at = NULL, updated_at = now()
WHERE workspace_uuid = #{workspaceUUID} AND external_id = #{externalID}
AND status = 'active' AND revision = #{expectedRevision}

